<!doctype html><html><head><meta charset="utf-8"><title>Salary Slip</title><style>body{font-family:DejaVu Sans,Arial,sans-serif;color:#172033;margin:35px;font-size:12px}.head{display:flex;justify-content:space-between;border-bottom:3px solid #0794b5;padding-bottom:18px}.brand{font-size:22px;font-weight:bold;color:#101936}.brand span{color:#0794b5}.right{text-align:right}.details{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:25px 0;padding:18px;background:#f5f7fa}.details div{display:flex;justify-content:space-between}.details span{color:#667085}table{width:100%;border-collapse:collapse}th{background:#101936;color:#fff;padding:10px;text-align:left}td{padding:10px;border-bottom:1px solid #e4e7ec}.right{text-align:right}.net{margin:25px 0 0 auto;width:45%;padding:16px;background:#ddf5f7;display:flex;justify-content:space-between;font-size:17px;font-weight:bold}.foot{text-align:center;color:#667085;border-top:1px solid #e4e7ec;margin-top:45px;padding-top:15px}</style></head><body><div class="head"><div><div class="brand">Rankers <span>Mind</span></div><div>Kolkata, West Bengal, India</div></div><div class="right"><h1>Salary Slip</h1><strong><?= e(date('F Y',strtotime($entry['period_month']))) ?></strong></div></div><div class="details"><div><span>Employee</span><strong><?= e($entry['name']) ?></strong></div><div><span>Employee code</span><strong><?= e($entry['employee_code']) ?></strong></div><div><span>Department</span><strong><?= e($entry['department_name']?:'—') ?></strong></div><div><span>Designation</span><strong><?= e($entry['designation_name']?:'—') ?></strong></div><div><span>Payroll status</span><strong><?= e($entry['payroll_status']) ?></strong></div><div><span>Payable days</span><strong><?= e($entry['payable_days']) ?></strong></div></div><table><thead><tr><th>Earnings</th><th class="right">Amount</th><th>Deductions</th><th class="right">Amount</th></tr></thead><tbody><tr><td>Basic earned salary</td><td class="right"><?= money($entry['basic_earned']) ?></td><td>Late deduction</td><td class="right"><?= money($entry['late_deduction']) ?></td></tr><tr><td>Overtime</td><td class="right"><?= money($entry['overtime_amount']) ?></td><td>Absence deduction</td><td class="right"><?= money($entry['absence_deduction']) ?></td></tr><tr><td>Bonus & incentive</td><td class="right"><?= money($entry['bonus']+$entry['incentive']) ?></td><td>Salary advance</td><td class="right"><?= money($entry['advance_deduction']) ?></td></tr><tr><td>Reimbursement</td><td class="right"><?= money($entry['reimbursement']) ?></td><td>Tax & other</td><td class="right"><?= money($entry['tax_deduction']+$entry['other_deduction']) ?></td></tr><tr><td><strong>Gross pay</strong></td><td class="right"><strong><?= money($entry['gross_pay']) ?></strong></td><td><strong>Total deductions</strong></td><td class="right"><strong><?= money($entry['total_deduction']) ?></strong></td></tr></tbody></table><div class="net"><span>Net salary</span><span><?= money($entry['net_pay']) ?></span></div><p>Attendance: <?= e($entry['present_days']) ?> present · <?= e($entry['absent_days']) ?> absent · <?= e($entry['half_days']) ?> half days · <?= e($entry['late_count']) ?> late arrivals</p><div class="foot">This is a system-generated salary slip from Rankers Mind CRM.</div></body></html>
